INSERT INTO `brand` (`id`, `created_by`, `updated_by`, `slug`, `title`, `parent`, `ord`, `created_at`, `updated_at`, `status`, `logo`, `anons`, `website_url`, `email`, `phone`, `address`, `description`, `instagram_url`, `telegram_url`, `vkontakte_url`, `youtube_url`, `city`, `first_letter`)
VALUES
	(1,1,1,'telodvigeniya','Телодвижения',0,0,'2025-11-05 18:51:30','2025-11-15 18:53:21','active','1763232801845_a7ad36d59e580a68.jpg','«Телодвижения» - российский бренд одежды с собственным производством, предлагающий широкий выбор товаров для создания повседневного гардероба.\r\n\r\nБолее 9 лет мы создаем качественную базовую одежду и объединяем людей, которые ценят как комфорт и практичность, так и стремление к новым горизонтам и амбициозность.','https://telodvigeniya.ru/','info@telodvigeniya.ru','+79003134281','Саратов','О компании\r\nИстория компании началась в 2014 году, когда один из основателей компании посетил молодёжный форум - там зародилась идея создания бренда, в основе которого лежат лидерство, энергичность и желание двигаться вперед. Воплотить мечту в реальность помогла команда единомышленников: полная самоотдача и уверенность в будущем успехе помогли построить большую компанию, внутри которой, так же как и тогда, живут и ценятся трудолюбие и стремление к постоянному развитию. Таким образом, была сформулирована миссия компании - помогать людям раскрывать свой потенциал.\r\n\r\nСегодня компания насчитывает 16 производственных площадок в разных городах России, а над её созданием трудится больше 1 000 человек.\r\n\r\nФраза, некогда сказанная одним из основателей – «Для тех, у кого всё будет», стала слоганом бренда.',NULL,'https://t.me/+AKAc-lXliRBmZWYy','https://vk.com/telodvigeniya','https://m.youtube.com/@TELODVIGENIYA','Саратов','Т'),
	(2,1,1,'de4444th','DE4444TH',0,0,'2025-11-07 06:11:31','2025-11-15 18:56:10','active','1763232970157_b3a3490503e1aaf6.jpg','Бренд стритвир одежды. Cоздаем мерч для современных исполнителей.\r\n\r\nОдной из главных наших особенностей являются кастомные вещи, выполненные вручную. Эти изделия могут быть как в единичных экземплярах, так и в большом тираже.\r\nКаждая из них также окрашивается художником, придавая вещам неповторимость.\r\n\r\nБренд стал популярным благодаря одежде\r\nс изображениями культовых рэперов, ушедших из жизни, таких как Lil Peep, XXXTentacion и 2Pac. Эти вещи до сих пор вызывают большой интерес и обсуждения среди поклонников.','https://de4444th.com',NULL,NULL,'Красноярск',NULL,NULL,NULL,NULL,NULL,'Красноярск','D'),
	(3,1,1,'tisval','TISVAL',0,0,'2025-11-07 08:10:08','2025-11-15 18:56:11','active','1763232971269_72f7b2cf61ca938f.jpg','В TISVAL мы строим всё на премиальном качестве — от выбора материалов до обслуживания клиентов. Каждая деталь, каждая строчка и каждый элемент дизайна проходят строгий контроль, чтобы вещи служили долго и выглядели безупречно.\r\n\r\nМы создаем нашу одежду в России, со следами разных культур, все модели выполнены oversize крое.\r\n\r\nНо для нас важно не только качество вещей, но и твой опыт взаимодействия с брендом. Мы стремимся создать сервис, который соответствует нашему продукту: внимательный, открытый и всегда на высоте.','https://tisval.ru/',NULL,NULL,'Москва','TISVAL — это бренд, основанный двумя друзьями, которые однажды приняли решение отказаться от наёмной работы, чтобы обрести свободу и создать нечто по-настоящему своё. С самого начала мы стремились к вещам, в которых соединяются точность, характер и комфорт. Мы не гнались за эффектностью — нас интересовало другое: как должна выглядеть одежда, чтобы отражать внутреннюю собранность и вкус, при этом быть живой, пластичной и уместной в разных контекстах.\r\n\r\n\r\n\r\nВ TISVAL особое внимание уделяется выбору материалов. Мы работаем только с тканями высокого качества, тщательно проверяем посадку, лично тестируем каждую модель. Производство TISVAL находится в России. Это наш принципиальный выбор — быть рядом с процессом, лично контролировать качество и участвовать в создании каждой вещи на всех этапах. Мы сотрудничаем с опытными мастерами, небольшими цехами и студиями, где ценят точность, аккуратность и внимание к деталям. Такой формат позволяет не просто выпускать одежду, а выстраивать устойчивую, прозрачную систему работы — без лишнего, без компромиссов.\r\n\r\n\r\n\r\nРаботая здесь, мы поддерживаем развитие современной фэшен-культуры в России, создаём рабочие места и инвестируем в качество, которое рождается внутри страны. Для нас это не про «удобно» или «дешевле». Это про ответственность — перед продуктом, перед командой, перед теми, кто выбирает TISVAL. Крой мы продумываем так, чтобы одежда не сковывала движения и не требовала усилий при носке — силуэты чистые, немного расслабленные, но при этом собранные, сдержанные и выразительные.\r\n\r\nПринты разрабатываются в коллаборации с художниками и графическими дизайнерами, и становятся частью визуального языка бренда, а не просто украшением.\r\n\r\n\r\n\r\nВажной частью нашей философии является сервис. Мы внимательно относимся к каждому клиенту — от первого контакта до момента, когда вещь оказывается в руках. Доставка работает быстро и аккуратно, упаковка продумана до мелочей, а обратная связь всегда остаётся открытой. Мы выстраиваем общение так, чтобы человек чувствовал: он не просто оформил заказ, а стал частью пространства, где ценят внимание, вкус и уважение к личному выбору.\r\n\r\n\r\n\r\nTISVAL — это одежда для тех, кто мыслит точно, выбирает внимательно и чувствует себя свободно в каждом решении. Нам близки люди, которые умеют замечать форму, ценят эстетику повседневного, и не нуждаются в лишних словах. Мы не создаём моду — мы создаём одежду, в которой удобно быть собой.',NULL,NULL,NULL,NULL,'Москва','T'),
