	(333,2,1,'gate31','GATE31',0,0,'2025-11-07 09:32:52','2025-11-15 12:20:14','active',NULL,'GATE31 — это минималистичный бренд одежды из Санкт–Петербурга. \r\n\r\nМы стремимся к инновациям и создаем современную классику для женщин и мужчин всех возрастов, ведь продуманный базовый гардероб актуален для любого поколения.\r\n\r\nЭто концепция чистоты и минимализма, коллекции предельно красивых в своей простоте вещей, где главными становятся содержание и функция.','https://www.gate31.ru/','shop@gate31.ru','8 800 333 72 31','Россия, г. Санкт-Петербург','GATE31 — это минималистичный бренд одежды из Санкт-Петербурга\r\nМы начинали как магазин российских и корейских дизайнеров. INSERT INTO `brand_audience` (`id`, `description`, `created_by`, `updated_by`, `slug`, `title`, `parent`, `ord`, `created_at`, `updated_at`, `status`)
